import { useQuery } from "@tanstack/react-query";
import { getMessages } from "@/lib/api";
import { POLLING_INTERVALS, queryKeys } from "@/lib/query";

export function useMessages(conversationId: string | null, enabled = true) {
  return useQuery({
    queryKey: conversationId ? queryKeys.messages(conversationId) : ["messages"],
    queryFn: () => getMessages(conversationId as string),
    enabled: Boolean(conversationId) && enabled,
    refetchInterval: conversationId && enabled ? POLLING_INTERVALS.messages : false,
  });
}

"use client";

import { useEffect, useRef } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { EmptyState } from "@/components/inbox/inbox-states";
import { MessageComposer } from "@/components/inbox/message-composer";
import { queryKeys } from "@/lib/query";
import { type Conversation, type Message } from "@/lib/types";
import { cn, formatMessageStatus, formatMessageTime, formatPhoneNumber, getInitials } from "@/lib/utils";

type ChatPanelProps = {
  conversation: Conversation | null;
  messages: Message[];
  isLoading: boolean;
  isError: boolean;
  isCacheCleared: boolean;
  onBack: () => void;
  onRetry: () => void;
  onClearCache: () => void;
};

export function ChatPanel({
  conversation,
  messages,
  isLoading,
  isError,
  isCacheCleared,
  onBack,
  onRetry,
  onClearCache,
}: ChatPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const queryClient = useQueryClient();

  useEffect(() => {
    const element = scrollRef.current;
    if (!element) {
      return;
    }

    element.scrollTop = element.scrollHeight;
  }, [conversation?.id, messages.length]);

  function handleClearCache() {
    if (!conversation) {
      return;
    }

    queryClient.cancelQueries({ queryKey: queryKeys.messages(conversation.id) });
    queryClient.removeQueries({ queryKey: queryKeys.messages(conversation.id), exact: true });
    onClearCache();
  }

  if (!conversation) {
    return (
      <div className="hidden min-h-0 flex-1 lg:flex">
        <EmptyState
          title="Escolha uma conversa"
          description="Selecione um contato para visualizar o historico, responder com update otimista e usar a sugestao de IA."
        />
      </div>
    );
  }

  return (
    <section className="flex min-h-0 flex-1 flex-col rounded-[1.25rem] border border-border bg-surface shadow-sm">
      <header className="flex items-center gap-4 border-b border-border px-5 py-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-border bg-surface-muted text-muted transition hover:text-title lg:hidden"
          aria-label="Voltar para a lista de conversas"
        >
          ←
        </button>
        <div
          className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl text-sm font-semibold text-white"
          style={{ backgroundColor: conversation.avatarColor }}
        >
          {getInitials(conversation.contactName)}
        </div>
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-lg font-semibold text-title">{conversation.contactName}</h2>
          <p className="truncate text-sm text-muted">{formatPhoneNumber(conversation.contactPhone)}</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="hidden rounded-xl bg-green-500/10 px-3 py-1 text-xs font-medium text-green-500 sm:block">
            Sincronizacao ativa
          </div>
          <button
            type="button"
            onClick={handleClearCache}
            className="rounded-xl border border-border bg-surface-muted px-3 py-2 text-xs font-semibold text-muted transition hover:border-primary-hover hover:text-title"
          >
            Limpar cache local
          </button>
        </div>
      </header>

      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto px-4 py-5 sm:px-6">
        {isCacheCleared ? (
          <EmptyState
            title="Cache local limpo"
            description="O historico desta conversa foi removido apenas da memoria do navegador. Ao reativar a sincronizacao, a API pode repopular os dados."
          />
        ) : null}

        {!isCacheCleared && isLoading ? (
          <div className="space-y-3">
            {Array.from({ length: 5 }).map((_, index) => (
              <div key={index} className={cn("flex", index % 2 === 0 ? "justify-start" : "justify-end")}> 
                <div className="h-20 w-full max-w-md animate-pulse rounded-2xl bg-surface-muted" />
              </div>
            ))}
          </div>
        ) : null}

        {!isCacheCleared && !isLoading && isError ? (
          <EmptyState
            title="Erro ao carregar o chat"
            description="A conversa nao pode ser sincronizada agora. Tente novamente em instantes."
          />
        ) : null}

        {!isCacheCleared && !isLoading && !isError && messages.length === 0 ? (
          <EmptyState
            title="Nenhuma mensagem ainda"
            description="Inicie o atendimento manualmente ou gere uma sugestao de resposta com IA."
          />
        ) : null}

        {!isCacheCleared && !isLoading && !isError && messages.length > 0 ? (
          <ol className="space-y-3">
            {messages.map((message) => {
              const isAgent = message.direction === "out";

              return (
                <li key={message.id} className={cn("flex", isAgent ? "justify-end" : "justify-start")}>
                  <article
                    className={cn(
                      "max-w-[85%] rounded-2xl px-4 py-3 shadow-sm sm:max-w-[70%]",
                      isAgent ? "bg-primary text-white" : "bg-surface-muted text-title",
                    )}
                  >
                    <p className="text-sm leading-6">{message.body}</p>
                    <div
                      className={cn(
                        "mt-2 flex items-center justify-end gap-2 text-[11px] font-medium",
                        isAgent ? "text-white/70" : "text-muted",
                      )}
                    >
                      <span>{formatMessageStatus(message.status)}</span>
                      <time dateTime={message.createdAt}>{formatMessageTime(message.createdAt)}</time>
                    </div>
                  </article>
                </li>
              );
            })}
          </ol>
        ) : null}
      </div>

      {isError && !isCacheCleared ? (
        <div className="border-t border-border px-5 py-4">
          <button
            type="button"
            onClick={onRetry}
            className="rounded-xl bg-primary px-4 py-2 text-sm font-medium text-white transition hover:bg-primary-hover"
          >
            Recarregar conversa
          </button>
        </div>
      ) : (
        <MessageComposer conversationId={conversation.id} disabled={isCacheCleared} />
      )}
    </section>
  );
}

"use client";

import { useDeferredValue, useMemo, useState } from "react";
import { ChatPanel } from "@/components/inbox/chat-panel";
import { ConversationList } from "@/components/inbox/conversation-list";
import { useConversations } from "@/hooks/use-conversations";
import { useMessages } from "@/hooks/use-messages";
import { useProfile } from "@/hooks/use-profile";
import { cn, getInitials } from "@/lib/utils";

const attendantName = "Nelson Silva";
const attendantInitials = getInitials(attendantName);
const attendantRole = "Suporte NeoFribra";

export function InboxApp() {
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [clearedConversationId, setClearedConversationId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const deferredSearchTerm = useDeferredValue(searchTerm);

  const profileQuery = useProfile();
  const conversationsQuery = useConversations();
  const selectedConversation =
    conversationsQuery.data?.find(
      (conversation) => conversation.id === selectedConversationId,
    ) ?? null;
  const isCacheCleared = clearedConversationId === selectedConversationId;
  const messagesQuery = useMessages(selectedConversationId, !isCacheCleared);

  const filteredConversations = useMemo(() => {
    const conversations = conversationsQuery.data ?? [];
    const normalizedTerm = deferredSearchTerm.trim().toLowerCase();

    if (!normalizedTerm) {
      return conversations;
    }

    return conversations.filter((conversation) =>
      [conversation.contactName, conversation.contactPhone, conversation.lastMessage]
        .join(" ")
        .toLowerCase()
        .includes(normalizedTerm),
    );
  }, [conversationsQuery.data, deferredSearchTerm]);

  function handleSelectConversation(conversationId: string) {
    setSelectedConversationId(conversationId);
    setClearedConversationId(null);
  }

  function handleClearCache() {
    setClearedConversationId(selectedConversationId);
  }

  return (
    <main className="min-h-screen bg-background px-4 py-4 text-title sm:px-6 lg:px-8 lg:py-8">
      <div className="mx-auto flex min-h-[calc(100vh-2rem)] max-w-7xl flex-col gap-4 lg:min-h-[calc(100vh-4rem)] lg:flex-row">
        <div className={cn("min-h-0 lg:flex", selectedConversationId ? "hidden lg:flex" : "flex")}>
          <ConversationList
            conversations={filteredConversations}
            activeConversationId={selectedConversationId}
            isLoading={conversationsQuery.isLoading}
            isError={conversationsQuery.isError}
            searchTerm={searchTerm}
            onSearchTermChange={setSearchTerm}
            onSelectConversation={handleSelectConversation}
            onRetry={() => conversationsQuery.refetch()}
          />
        </div>

        <div className={cn("min-h-0 flex-1", selectedConversationId ? "flex" : "hidden lg:flex")}>
          <div className="flex min-h-0 flex-1 flex-col gap-4">
            <section className="rounded-[1.25rem] border border-border bg-surface px-5 py-4 shadow-sm">
              <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                <div className="flex flex-col gap-3">
                  <p className="text-xs font-semibold uppercase tracking-[0.28em] text-primary">
                    Painel ativo
                  </p>

                  <div className="flex items-start gap-4">
                    <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary text-sm font-semibold text-white shadow-sm">
                      {attendantInitials}
                    </div>

                    <div>
                      <h1 className="text-2xl font-semibold tracking-tight text-title">
                        {attendantName}
                      </h1>
                      <p className="mt-1 text-sm text-muted">{attendantRole}</p>
                    </div>
                  </div>
                </div>

                <div className="flex flex-wrap gap-3 text-sm text-muted">
                  <div className="rounded-xl bg-surface-muted px-3 py-2">

                      {conversationsQuery.data?.length ?? 0} conversas monitoradas

                  </div>
                  <div className="rounded-xl bg-green-500/10 px-3 py-2 text-green-500">
                      {selectedConversation ? "Chat em foco" : "Nenhum chat selecionado"}
                  </div>
                  <div
                    className={cn(
                      "rounded-xl px-3 py-2",
                      profileQuery.isError
                        ? "bg-surface-muted text-muted"
                        : "bg-green-500/10 text-green-500",
                    )}
                  >
                    {profileQuery.isError ? "API instavel" : "API conectada"}
                  </div>
                </div>
              </div>
            </section>

            <ChatPanel
              conversation={selectedConversation}
              messages={messagesQuery.data ?? []}
              isLoading={messagesQuery.isLoading}
              isError={messagesQuery.isError}
              isCacheCleared={isCacheCleared}
              onBack={() => setSelectedConversationId(null)}
              onRetry={() => messagesQuery.refetch()}
              onClearCache={handleClearCache}
            />
          </div>
        </div>
      </div>
    </main>
  );
}
